@@ -65,3 +54,65 @@ export default function Admin() {
     </Box>
   )
 }
+
+function AdminRoutes() {
+  // eslint-disable-next-line import/namespace
+  const Routes = Router['Routes']
+
+  if (!Routes) {
+    return (
+      <Router.Switch>
+        <Router.Redirect from="/" exact to="/users" />
+        <Router.Route path="/users" exact>
+          <Users />
+        </Router.Route>
+        <Router.Route path="/users/:userId">
+          {({ match }) => <User userId={match.params.userId} />}
+        </Router.Route>
+        <Router.Route path="/groups" exact>
+          <Groups />
+        </Router.Route>
+        <Router.Route path="/groups/:groupId">
+          {({ match }) => <Group groupId={match.params.groupId} />}
+        </Router.Route>
+      </Router.Switch>
+    )
+  }
+
+  return (
+    <Routes>
+      <Router.Route path="/" element={<RedirectTo to="/users" />} />
+      <Router.Route path="/users" element={<Users />} />
+      <Router.Route path="/users/:userId" element={<UserRoute />} />
+      <Router.Route path="/groups" element={<Groups />} />
+      <Router.Route path="/groups/:groupId" element={<GroupRoute />} />
+    </Routes>
+  )
+}
+
+function RedirectTo({ to }) {
+  // eslint-disable-next-line import/namespace
+  const Navigate = Router['Navigate']
+
+  if (!Navigate) {
+    return <Router.Redirect to={to} />
+  }
+
+  return <Navigate replace to={to} />
+}
+
+RedirectTo.propTypes = {
+  to: T.string.isRequired
+}
+
+function UserRoute() {
+  const { userId } = Router.useParams()
+
+  return <User userId={userId} />
+}
+
+function GroupRoute() {
+  const { groupId } = Router.useParams()
+
+  return <Group groupId={groupId} />
+}
